import type { LinterContext } from '@teambit/linter';
import { computeOxlintNodeOptions } from './compute-options.js';

function context(
  overrides: Partial<Pick<LinterContext, 'fix' | 'fixTypes'>> = {}
): LinterContext {
  return {
    fix: false,
    fixTypes: ['layout', 'problem', 'suggestion'],
    ...overrides,
  } as LinterContext;
}

it('uses one JSON process and does not enable fixes by default', () => {
  expect(
    computeOxlintNodeOptions(
      { formats: ['default'], fixesFlags: {} },
      context()
    )
  ).toMatchObject({ formats: ['json'], fixesFlags: {} });
});

it('maps the standard Bit --fix option to safe Oxlint fixes', () => {
  expect(
    computeOxlintNodeOptions({}, context({ fix: true })).fixesFlags
  ).toEqual({ all: true });
});

it('keeps Oxlint suggestion and dangerous fixes opt-in', () => {
  expect(
    computeOxlintNodeOptions(
      {},
      context({
        fix: true,
        fixTypes: ['suggestions', 'dangerously'],
      })
    ).fixesFlags
  ).toEqual({ all: true, suggestions: true, dangerously: true });
});
